use num_bigint::BigInt;
use num_traits::ToPrimitive;

/// Squares each element of the input vector, returning a new vector of the same length.
/// Uses BigInt to match "mathematical integers" (no overflow).
pub fn square_elements(a: Vec<BigInt>) -> Vec<BigInt> {
    a.into_iter().map(|x| &x * &x).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use num_bigint::ToBigInt;

    #[test]
    fn squares_basic() {
        let a = vec![
            (-3).to_bigint().unwrap(),
            0.to_bigint().unwrap(),
            4.to_bigint().unwrap(),
        ];
        let out = square_elements(a);
        assert_eq!(out[0], 9.to_bigint().unwrap());
        assert_eq!(out[1], 0.to_bigint().unwrap());
        assert_eq!(out[2], 16.to_bigint().unwrap());
    }

    #[test]
    fn handles_empty() {
        let a: Vec<BigInt> = vec![];
        let out = square_elements(a);
        assert!(out.is_empty());
    }

    #[test]
    fn handles_large() {
        // 10^100 squared = 10^200
        let ten = 10.to_bigint().unwrap();
        let big = ten.pow(100u32);
        let out = square_elements(vec![big.clone()]);
        assert_eq!(out[0], ten.pow(200u32));
    }
}